import numpy as np
import xarray as xr
from satpy.readers.fci_l1c_nc import ConcertoFCIL1cNCReader
from satpy.readers.core.file_handlers import BaseFileHandler

class FakeFCIFileHandler(BaseFileHandler):
    def __init__(self, filename, filename_info, filetype_info):
        super().__init__(filename, filename_info, filetype_info)
        self.filename = filename
        self.file_content = {}

    def __getitem__(self, key):
        if key == "data/ir_105/measured/effective_radiance":
            data = xr.DataArray(
                np.array([1, 2, 3], dtype="uint16"),
                dims=("x",),
                attrs={"_FillValue": 65535, "scale_factor": 0.1, "add_offset": 0, "units": "counts", "ancillary_variables": "pixel_quality"}
            )
            return data
        return None

    def get_and_cache_npxr(self, key):
        return np.array(1.0)

    def get_channel_measured_group_path(self, name):
        return f"data/{name}/measured"

def test_drop_fill_value():
    filename = "fake.nc"
    filename_info = {"filename": filename}
    filetype_info = {"file_type": "FDHSI"}

    # We need to mock the reader's file handlers
    reader = ConcertoFCIL1cNCReader([filename], filename_info, filetype_info)
    # Mock the file handler
    reader.file_handlers = [FakeFCIFileHandler(filename, filename_info, filetype_info)]

    # Test for brightness_temperature (should drop _FillValue)
    key_bt = {"name": "ir_105", "calibration": "brightness_temperature", "resolution": "low"}
    # We need to mock the key object if it's expected to have to_dict()
    class MockKey:
        def __init__(self, d): self.d = d
        def to_dict(self): return self.d
        def __getitem__(self, item): return self.d[item]
        def __contains__(self, item): return item in self.d

    key_bt = MockKey(key_bt)
    res_bt = reader._get_dataset_measurand(key_bt)
    print(f"BT attrs: {res_bt.attrs}")
    assert "_FillValue" not in res_bt.attrs, "_FillValue should be dropped for brightness_temperature"

    # Test for counts (should keep _FillValue)
    key_counts = {"name": "ir_105", "calibration": "counts", "resolution": "low"}
    key_counts = MockKey(key_counts)
    res_counts = reader._get_dataset_measurand(key_counts)
    print(f"Counts attrs: {res_counts.attrs}")
    assert "_FillValue" in res_counts.attrs, "_FillValue should be kept for counts"

if __name__ == "__main__":
    try:
        test_drop_fill_value()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()
        exit(1)

